codeExample.code:
param location string = resourceGroup().location
param appName string

resource storage 'Microsoft.Storage/storageAccounts@2023-05-01' = {
  name: '${appName}store'
  location: location
  sku: { name: 'Standard_LRS' }
  kind: 'StorageV2'
  properties: {
    allowBlobPublicAccess: false
    minimumTlsVersion: 'TLS1_2'
    // No shared keys: with these disabled the only way in is Entra ID,
    // so a leaked key cannot exist because there is no key.
    allowSharedKeyAccess: false
  }
}

resource app 'Microsoft.Web/sites@2023-12-01' = {
  name: appName
  location: location
  identity: { type: 'SystemAssigned' }   // the platform issues the token
  properties: {
    httpsOnly: true
    siteConfig: {
      appSettings: [
        // The account name, not a connection string. There is no secret
        // here to appear in a pipeline log or a configuration export.
        { name: 'STORAGE_ACCOUNT', value: storage.name }
      ]
    }
  }
}

// Storage Blob Data Contributor, scoped to this account only. Declared here
// rather than clicked in the portal, so it survives a rebuild and is visible
// in review.
var blobContributor = 'ba92f5b4-2d11-453d-a403-e96b0029c9fe'

resource grant 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  scope: storage
  name: guid(storage.id, app.id, blobContributor)
  properties: {
    principalId: app.identity.principalId
    principalType: 'ServicePrincipal'
    roleDefinitionId: subscriptionResourceId(
      'Microsoft.Authorization/roleDefinitions', blobContributor)
  }
}
